UPDATE service_order
SET status              = 'DOING',
    instrument_snapshot = #{instrumentSnapshot},
    updated_at          = #{updatedAt}
WHERE id = #{id}
  AND status = 'PLANNED'

UPDATE service_order
SET status      = #{status},
    result_note = #{resultNote},
    updated_at  = #{updatedAt}
WHERE id = #{id}

UPDATE service_order
SET status        = #{newStatus},
    current_round = #{currentRound},
    updated_at    = #{updatedAt}
WHERE id = #{id}
  AND status = #{expectedStatus}

